// Music provider registry for `launchclip finish` (RFC §9).
//
//   synth       the procedural, license-free bed from synth-audio-kit.mjs
//   elevenlabs  generated by the ElevenLabs music API (paid, cached)
//   file        a track the project supplies under assets/
//
// resolveMusicChoice() turns the --music flag, storyboard audio.music and the
// environment into one decision; finish then asks the provider for a track.

export const MUSIC_PROVIDERS = Object.freeze(["synth", "elevenlabs", "file"]);
export const MUSIC_FLAG_VALUES = Object.freeze(["synth", "elevenlabs", "none"]);
export const MUSIC_SYNC_MODES = Object.freeze(["auto", "off", "cuts", "hits"]);

/**
 * audio.music → normalised spec (no environment involved):
 * {provider: "synth"|"elevenlabs"|"file"|"none"|null, file?, prompt?, bpm?,
 * key?, seed?, model?, sync, volume?}. provider null means the story leaves
 * the choice to finish (the default).
 */
export function parseMusicSpec(music) {
  if (music === undefined || music === null) return { provider: null, sync: "auto" };
  if (music === false || music === "none") return { provider: "none", sync: "off" };
  if (music === "synth") return { provider: "synth", sync: "auto" };
  if (music === "elevenlabs") return { provider: "elevenlabs", sync: "auto" };
  if (typeof music === "string") return { provider: "file", file: music, sync: "auto" };
  if (typeof music !== "object") return { provider: null, sync: "auto" };
  const file = music.file ?? (music.source && music.source !== "synth" ? music.source : undefined);
  let provider = music.provider ?? null;
  if (!provider && music.source === "synth") provider = "synth";
  if (!provider && file) provider = "file";
  const spec = { provider, sync: MUSIC_SYNC_MODES.includes(music.sync) ? music.sync : "auto" };
  if (file) spec.file = file;
  for (const key of ["prompt", "bpm", "key", "seed", "model", "volume"]) if (music[key] !== undefined) spec[key] = music[key];
  return spec;
}

/** --music-volume: a gain from 0 to 1. Throws on anything else. */
export function parseMusicVolume(value) {
  const volume = value === true || value === "" ? NaN : Number(value);
  if (!(Number.isFinite(volume) && volume >= 0 && volume <= 1)) throw new Error(`--music-volume must be a number from 0 to 1; got ${value}`);
  return volume;
}

/** --music-prompt: a non-empty style prompt for the ElevenLabs track (trimmed, at most 1000 characters). Throws on anything else. */
export function parseMusicPrompt(value) {
  const prompt = typeof value === "string" ? value.trim() : "";
  if (!prompt) throw new Error("--music-prompt needs the music's style in words, for example \"warm acoustic guitar, steady, unobtrusive\"");
  return prompt.slice(0, 1000);
}

/**
 * --music-duck: the bed's level under speech as a share of its level in the
 * pauses, 0–1 (0.42: it drops to 42 %, about -7.5 dB; 1: no ducking).
 * Throws on anything else.
 */
export function parseMusicDuck(value) {
  const duck = value === true || value === "" ? NaN : Number(value);
  if (!(Number.isFinite(duck) && duck >= 0 && duck <= 1)) throw new Error(`--music-duck must be a number from 0 to 1 (the music's level under speech as a share of its level in pauses); got ${value}`);
  return duck;
}

/**
 * The music decision for one finish run.
 * flag: --music synth|elevenlabs|none (wins); env: for ELEVENLABS_API_KEY.
 * Default: elevenlabs when the key is set and the story does not choose, else synth.
 * → {provider, ...spec, reason, warnings: []}
 */
export function resolveMusicChoice(audio, { flag, env = process.env } = {}) {
  const spec = parseMusicSpec(audio?.music);
  const warnings = [];
  const hasKey = Boolean(env?.ELEVENLABS_API_KEY);
  if (flag !== undefined && flag !== null && flag !== true) {
    const value = String(flag).toLowerCase();
    if (!MUSIC_FLAG_VALUES.includes(value)) throw new Error(`--music must be one of ${MUSIC_FLAG_VALUES.join(", ")}; got ${flag}`);
    if (value === "elevenlabs" && !hasKey) throw new Error("--music elevenlabs needs ELEVENLABS_API_KEY (set it in the shell or .env). Nothing was sent.");
    const choice = { ...spec, provider: value, reason: `--music ${value}`, warnings };
    if (value !== "file") delete choice.file;
    if (value === "none") choice.sync = "off";
    return choice;
  }
  if (spec.provider === "elevenlabs" && !hasKey) {
    warnings.push("audio.music asks for ElevenLabs but ELEVENLABS_API_KEY is not set; using the procedural synth bed");
    return { ...spec, provider: "synth", reason: "audio.music elevenlabs without a key", warnings };
  }
  if (spec.provider) return { ...spec, reason: `audio.music ${spec.provider}`, warnings };
  return { ...spec, provider: hasKey ? "elevenlabs" : "synth", reason: hasKey ? "default: ELEVENLABS_API_KEY is set" : "default: no ELEVENLABS_API_KEY", warnings };
}

/**
 * A provider by name. options: {env, fetch, cacheDir, synthKit, ...}.
 * Providers expose generate(story, params, {outFile}) → {file, cached, ...}.
 */
export async function getMusicProvider(name, options = {}) {
  const key = String(name ?? "").toLowerCase();
  if (key === "elevenlabs") {
    const { create } = await import("./elevenlabs.js");
    return create(options);
  }
  if (key === "synth") return createSynthProvider(options);
  if (key === "file") return createFileProvider(options);
  throw new Error(`Unknown music provider "${name}". Available providers: ${MUSIC_PROVIDERS.join(", ")}`);
}

// The procedural bed. synthKit(outDir, bed) is finish's adapter around
// synth-audio-kit.mjs; it writes <outDir>/music/bed.wav and BEATS.json.
function createSynthProvider({ synthKit } = {}) {
  return {
    name: "synth",
    paid: false,
    async generate(_story, { bed, outDir } = {}) {
      if (typeof synthKit !== "function") throw new Error("the synth music provider needs a synthKit adapter");
      await synthKit(outDir, bed);
      return { file: `${outDir}/music/bed.wav`, cached: false };
    }
  };
}

function createFileProvider() {
  return {
    name: "file",
    paid: false,
    async generate(_story, { file } = {}) {
      if (!file) throw new Error("the file music provider needs audio.music.file (an assets/ path)");
      return { file, cached: true };
    }
  };
}
